static_checks.command:
mkdir -p /tmp/bsf-sarif && rm -f /tmp/bsf-sarif/mypy.sarif /tmp/bsf-sarif/mypy.jsonl; .venv/bin/mypy --output json --no-error-summary app > /tmp/bsf-sarif/mypy.jsonl; rc=$?; .venv/bin/python -I - "$rc" /tmp/bsf-sarif/mypy.jsonl /tmp/bsf-sarif/mypy.sarif <<'MYPY_SARIF'
import json, sys

rc, src, dst = int(sys.argv[1]), sys.argv[2], sys.argv[3]
if rc not in (0, 1):
    sys.exit(
        "mypy exited %d, which is a crash or a bad invocation rather than findings; "
        "writing no SARIF so the gate drops this check instead of reading it as clean" % rc
    )

results = []
with open(src, encoding="utf-8") as fh:
    for line in fh:
        line = line.strip()
        if not line.startswith("{"):
            continue
        d = json.loads(line)
        if d.get("severity") == "note":
            continue
        results.append({
            "ruleId": d.get("code") or "mypy",
            "level": "error" if d.get("severity") == "error" else "warning",
            "message": {"text": d.get("message") or "mypy finding"},
            "locations": [{
                "physicalLocation": {
                    "artifactLocation": {"uri": d.get("file") or ""},
                    "region": {"startLine": max(1, int(d.get("line") or 1))},
                }
            }],
        })

sarif = {
    "version": "2.1.0",
    "$schema": "https://json.schemastore.org/sarif-2.1.0.json",
    "runs": [{
        "tool": {"driver": {"name": "mypy", "informationUri": "https://mypy-lang.org/"}},
        "results": results,
    }],
}
with open(dst, "w", encoding="utf-8") as fh:
    json.dump(sarif, fh)
print("mypy: %d finding(s) written to %s" % (len(results), dst))
MYPY_SARIF
